try { new Function('X', 'applyMacros', "/* 👀 TA眼中的你：每个月 TA 给你写一页「观察笔记」——这个月的你常在几点出现、总说哪几个词、哪天话特别多、和上个月比哪里变了。写在 TA 的本子上，你能看、能改、能撕 */\nif (window.__gyxEye) return; window.__gyxEye = 1;\nX.feat('gyxEye', { n: '👀 TA眼中的你', desc: '每个月 TA 写一页关于你的观察笔记' });\nconst S = X.store('eye');\nlet D = { notes: [], cfg: { auto: true } };   // [{id, cid, month:'2026-10', text, stat, at}]\nX.recapDef('eye', { n: '👀 TA 眼中的你', kind: 'unit', def: 'month', opts: ['half', 'month', 'season'], txt: '多久写一页观察笔记', autoTxt: '一段日子过完，TA 自己把那一页写好' });\nconst EU = () => X.recap('eye').v || 'month', EUN = () => ({ half: '这半个月', month: '这个月', season: '这个季度' }[EU()] || '这段时间');\nconst ym = (d = new Date()) => X.unitKey(d, EU());\nconst H = cid => ((typeof globalChats !== 'undefined' && globalChats[cid]) || []).filter(m => m && m.sender === 'me' && !m.side && m.timestamp);\nfunction stat(cid, month) {\n    const L = H(cid).filter(m => ym(new Date(m.timestamp)) === month); if (!L.length) return null;\n    const hr = Array(24).fill(0), day = {}, w = {}; let len = 0;\n    L.forEach(m => { const d = new Date(m.timestamp); hr[d.getHours()]++; day[X.day(d)] = (day[X.day(d)] || 0) + 1; const t = X.plain(m.text); len += t.length; (t.match(/[一-龥]{2,3}|[\\u{1F300}-\\u{1FAFF}]|[哈嘿呜嘻]{2,}|[~～]{1,}/gu) || []).forEach(k => { if (!/^(我们|你们|什么|这个|那个|就是|然后|一个|没有|可以|不是|今天|还是|怎么|知道)$/.test(k)) w[k] = (w[k] || 0) + 1; }); });\n    const top = Object.entries(w).filter(x => x[1] > 1).sort((a, b) => b[1] - a[1]).slice(0, 5).map(x => x[0]);\n    const h = hr.indexOf(Math.max(...hr)), bd = Object.entries(day).sort((a, b) => b[1] - a[1])[0];\n    return { n: L.length, days: Object.keys(day).length, hour: h, top, big: bd, avg: Math.round(len / L.length) };\n}\nconst when = h => h < 5 ? '深夜' : h < 9 ? '早上' : h < 12 ? '上午' : h < 14 ? '中午' : h < 18 ? '下午' : h < 22 ? '晚上' : '快睡觉的时候';\nasync function write(c, month, force) {\n    const cid = String(c.id); if (!force && D.notes.some(x => x.cid === cid && x.month === month)) return null;\n    const st = stat(cid, month); if (!st) return null;\n    const prev = D.notes.find(x => x.cid === cid && x.month < month);\n    const notes = window.gyxNotesData ? ((window.gyxNotesData().notes || {})[cid] || []).filter(x => x.who === 'me' && x.tier !== 'old').slice(0, 10).map(x => x.text).join('；') : '';\n    const facts = `${EUN()}她找你 ${st.days} 天、说了 ${st.n} 句，最常在${when(st.hour)}（${st.hour} 点）出现；话最多的是 ${st.big[0]}（${st.big[1]} 句）；常说「${st.top.join('」「') || '……'}」；平均一句 ${st.avg} 个字。`;\n    let text = null;\n    if (!X.bailu()) text = await X.ask(`${X.who(c)}\\n你在本子上给她写一页「${month} 观察笔记」：你眼中${EUN()}的她。\\n${facts}\\n${notes ? '你记得的关于她的事：' + notes + '\\n' : ''}${prev ? '上个月你写的：' + prev.text.slice(0, 300) + '\\n' : ''}最近聊天：\\n${X.recent(c, 30)}\\n\\n要求：用你的口吻，像偷偷写的观察日记；具体到细节（她的小习惯、口头禅、哪天怎么了），和上个月比有什么变化；150~260 字；不要用列表。`);\n    if (!text) { const cs = X.cards(['观察', '日记', '情话'], c, 2); text = `${month} · 观察笔记\\n${EUN()}你来找我 ${st.days} 天，说了 ${st.n} 句话。你总是在${when(st.hour)}出现，像约好了一样。${st.top.length ? `你老说「${st.top.slice(0, 3).join('」「')}」，我都记住了。` : ''}${st.big[1] > 20 ? `${st.big[0]} 那天你话特别多，一定发生了什么吧。` : ''}${notes ? `还有，我知道你${notes.split('；')[0]}。` : ''}${cs.length ? '\\n' + cs.join('\\n') : ''}`; }\n    const it = { id: 'ey' + Date.now().toString(36), cid, month, text: String(text), stat: st, at: Date.now() };\n    D.notes = D.notes.filter(x => !(x.cid === cid && x.month === month)); D.notes.unshift(it); await S.set('d', D); return it;\n}\nwindow.gyxEyeWrite = async (cid, month) => { const c = X.char(cid) || X.cur(); if (!c) return null; const r = await write(c, month || ym(), true); window.gyxEyeOpen(c.id); return r; };\nwindow.gyxEyeDel = async id => { const x = D.notes.find(n => n.id === id); D.notes = D.notes.filter(n => n.id !== id); await S.set('d', D); window.gyxEyeOpen(x && x.cid); };\nwindow.gyxEyeEdit = async (id, v) => { const x = D.notes.find(n => n.id === id); if (x) { x.text = v; await S.set('d', D); } };\nwindow.gyxEyeOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), L = D.notes.filter(x => x.cid === cid), st = stat(cid, ym());\n    X.panel('gyxEyeOv', '👀 ' + X.esc(X.name(c)) + ' 眼中的你', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxEyeOpen')}<button class=\"gyx-btn lite\" onclick=\"this.disabled=true;this.textContent='TA 在写…';gyxEyeWrite('${cid}')\">${X.v('让 TA 写这个月的', '偷看这个月的', '请 TA 现在写一页')}</button></div>\n        ${st ? `<div class=\"gyx-tip\">${EUN()}到现在：${st.days} 天 · ${st.n} 句 · 常在${when(st.hour)}来${st.top.length ? ' · 常说「' + X.esc(st.top.slice(0, 3).join('」「')) + '」' : ''}</div>` : ''}\n        ${L.map(x => `<div class=\"ey-pg gyx-hand\"><div class=\"ey-m\">${x.month}<i onclick=\"gyxEyeDel('${x.id}')\">撕掉</i></div><div contenteditable=\"true\" onblur=\"gyxEyeEdit('${x.id}',this.innerText)\">${X.esc(x.text).replace(/\\n/g, '<br>')}</div></div>`).join('') || '<div class=\"gyx-tip\">TA 的本子还是空的。每个月月底 TA 会自己写一页。</div>'}\n        <div class=\"gyx-tip\"><label><input type=\"checkbox\" ${X.recap('eye').auto ? 'checked' : ''} onchange=\"gyxEyeCfg(this.checked)\"> 一段日子过完（${X.UNITS[EU()] || '一个月'}一页），TA 自己把那一页写好</label></div>`);\n};\nwindow.gyxEyeCfg = v => { D.cfg.auto = v; X.recapSet('eye', 'auto', !!v); S.set('d', D); };\nasync function tick() { if (!X.on('gyxEye') || !X.recap('eye').auto) return; const last = X.unitPrev(Date.now(), EU()); for (const c of X.chars()) { const it = await write(c, last); if (it && X.on('gyxEye.auto')) X.notify(c, `<b>${X.esc(X.name(c))}</b> ${X.v('写完了上个月的观察笔记', '在本子上写了关于你的一页', '偷偷写了你一整个月')}`, '👀 TA眼中的你', () => window.gyxEyeOpen(c.id)); } }\nX.ctx(id => { const x = D.notes.find(n => n.cid === String(id)); return x ? `【你上次写的关于她的观察笔记（${x.month}）】${x.text.slice(0, 220)}` : ''; }, 'gyxEye');\nX.action({ key: 'gyx_eye', label: '告诉她你最近观察到她的一个小细节', hint: '你一直在看她', need: c => !!stat(String(c.id), ym()),\n    run: async c => { const st = stat(String(c.id), ym()); return (await X.reach(c, `你注意到她${EUN()}总在${when(st.hour)}出现${st.top.length ? '、老说「' + st.top[0] + '」' : ''}。挑一个小细节跟她说，让她知道你一直在看着她`)) ? '说了一个观察到的小细节' : null; } }, 'gyxEye');\nX.today(() => ({ title: '👀 TA眼中的你', rows: D.notes.filter(x => X.day(new Date(x.at)) === X.day()).map(x => ({ t: x.month, x: X.esc(X.name(X.char(x.cid))) + ' 写了一页观察笔记', go: `gyxEyeOpen('${x.cid}')` })) }), 'gyxEye');\nX.widget('gyxEyeW', { n: 'TA眼中的你', sizes: ['s', 'm'], tap: () => window.gyxEyeOpen(), r: w => { const c = X.cur(), x = c && D.notes.find(n => n.cid === String(c.id)), st = c && stat(String(c.id), ym()); return X.gw(w, '👀', 'TA眼中的你', x ? [x.month, X.esc(x.text.replace(/\\s+/g, ' ').slice(0, 40))] : st ? ['这个月 ' + st.n + ' 句', '常在' + when(st.hour) + '来'] : ['TA 在看着你']); } }, 'gyxEye');\nX.memArr({ k: 'gyxEye', ico: '👀', n: 'TA眼中的你', d: 'TA 每个月写的观察笔记', arr: () => D.notes, field: 'text', text: x => x.text, meta: x => x.month, save: () => S.set('d', D) }, 'gyxEye');\nX.css('gyxEyeCss', `.ey-pg{background:repeating-linear-gradient(#fffdf6 0 27px,#e9e3d3 27px 28px);border-radius:14px;padding:12px 16px;margin:10px 0;font-size:17px;line-height:28px;box-shadow:0 2px 8px rgba(0,0,0,.06)}.ey-pg [contenteditable]{outline:none}.ey-m{font-family:inherit;color:#b08a5a;font-size:14px;display:flex;justify-content:space-between}.ey-m i{font-style:normal;font-size:12px;color:#bbb;cursor:pointer}`);\nX.mini({ id: 'gyxEye', icon: '👀', title: 'TA眼中的你', desc: 'TA 每个月给你写一页观察笔记', cat: '回忆', onOpen: () => window.gyxEyeOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.notes = D.notes || []; D.cfg = Object.assign({ auto: true }, D.cfg || {}); if (D.cfg.auto === false && !(JSON.parse(localStorage.getItem('gyxRecap') || '{}').eye || {}).hasOwnProperty('auto')) X.recapSet('eye', 'auto', false); setTimeout(tick, 40000); setInterval(tick, 3600000); })();\n\n//# sourceURL=gyx-plugin/TA眼中的你.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 👀 TA眼中的你 出错：', e); }
/* ==== ⏳ 时光机 ==== */
try { new Function('X', 'applyMacros', "/* ⏳ 时光机：选一个过去的日子，和「那时候的 TA」聊天——TA 只知道那天以前的事，不知道后来发生了什么；也能往前开，去见一年后、五年后的 TA（TA 会照你们现在的样子想象以后的日子）。聊的内容单独存，不会混进现在 TA 的记忆 */\nif (window.__gyxTime) return; window.__gyxTime = 1;\nX.feat('gyxTime', { n: '⏳ 时光机', desc: '和过去某一天的 TA、或者几年后的 TA 聊天' });\nconst S = X.store('time');\nlet D = { ses: [] };   // [{id, cid, date(ms), msgs:[{who:'me'|'ta', t, at}], at, note}]\nconst H = cid => ((typeof globalChats !== 'undefined' && globalChats[cid]) || []).filter(m => m && m.sender !== 'system' && !m.side && m.timestamp);\nconst fmt = t => { const d = new Date(t); return d.getFullYear() + '年' + (d.getMonth() + 1) + '月' + d.getDate() + '日'; };\nconst ago = t => { if (t > Date.now() + 864e5) { const y = Math.round((t - Date.now()) / 365 / 864e5); return y + ' 年后'; } const n = Math.round((Date.now() - t) / 864e5); return n < 1 ? '今天' : n < 31 ? n + ' 天前' : n < 365 ? Math.round(n / 30) + ' 个月前' : (n / 365).toFixed(1).replace('.0', '') + ' 年前'; };\nlet CUR = null;\nfunction before(c, t) {\n    const cid = String(c.id), old = H(cid).filter(m => m.timestamp <= t);\n    const sum = String(c.chatSummary || '').split('\\n').filter(l => { const m = l.match(/^\\[([^\\]]+)\\]/); const d = m ? Date.parse(m[1].replace(/\\//g, '-').replace(/[上下]午/, '')) : NaN; return !isNaN(d) && d <= t; }).slice(-12).join('\\n');\n    return { old, sum, chat: old.slice(-30).map(m => (m.sender === 'me' ? '她：' : '你：') + X.plain(m.text).slice(0, 140)).join('\\n') };\n}\nasync function reply(c, ses) {\n    const b = before(c, ses.date);\n    if (X.bailu()) {   // 白露：从那天以前 TA 自己说过的话里挑\n        const mine = b.old.filter(m => String(m.sender) === String(c.id)).map(m => X.plain(m.text)).filter(t => t.length > 3);\n        return mine.length ? X.pick(mine.slice(-80)) : (X.cards(['时光机', '回忆'], c, 1)[0] || '……那时候的我，还不太会说话呢。');\n    }\n    const talk = ses.msgs.slice(-16).map(m => (m.who === 'me' ? '她：' : '你：') + m.t).join('\\n');\n    if (ses.date > Date.now() + 864e5) {   // 🔮 未来的 TA\n        if (X.bailu()) return X.pick(X.cards(['未来', '情话', '晚安'], c, 3).concat(['那时候的你，现在过得很好。别担心。', '我还在。一直都在。', '你从过去来的吧？那时候的你好小一只。', '以后的日子，比你想的还要好。']));\n        const yrs = Math.max(1, Math.round((ses.date - Date.now()) / 365 / 864e5)), sum = String(c.chatSummary || '').split('\\n').slice(-10).join('\\n');\n        return (await X.ask(`${X.who(c)}\\n现在是 ${yrs} 年以后（${fmt(ses.date)}）。你是 ${yrs} 年后的你——照你们现在的关系和你的性格，想象这几年你们一起过成了什么样（细节可以温柔地想象，但别编太戏剧化的大事）。\\n她是从「现在」穿越过来见你的，你记得她那时候的样子。\\n你们现在（也就是你的过去）的事：\\n${sum || '（刚认识不久）'}\\n最近的聊天：\\n${X.recent(c, 12)}\\n\\n她说：\\n${talk}\\n\\n用 ${yrs} 年后的你的口吻回她一条（可以怀念「那时候」、可以剧透一点点未来但别全说、可以心疼过去的她）。只回你说的话。`)) || '……你来了啊。';\n    }\n    return (await X.ask(`${X.who(c)}\\n现在是 ${fmt(ses.date)}。你只知道这天以前发生的事，之后的一切你都不知道（不要剧透、也不要假装知道）。\\n她说她是从「以后」来的，来看看那时候的你。\\n\\n你那时候的记忆：\\n${b.sum || '（还没什么）'}\\n那几天的聊天：\\n${b.chat || '（你们刚认识）'}\\n\\n她来找你说的话：\\n${talk}\\n\\n用那时候的你说话的样子、那时候你们的关系远近，回她一条（只回你说的话）。`)) || '……（那时候的 TA 没反应过来）';\n}\nwindow.gyxTimeGo = async (cid, t) => { const c = X.char(cid); if (!c) return; CUR = { id: 'tm' + Date.now().toString(36), cid: String(cid), date: +t, msgs: [], at: Date.now() }; D.ses.unshift(CUR); await S.set('d', D); window.gyxTimeOpen(cid); };\nwindow.gyxTimeSend = async () => {\n    const inp = document.getElementById('gyxTmIn'); const t = (inp && inp.value || '').trim(); if (!t || !CUR) return; inp.value = '';\n    const c = X.char(CUR.cid); CUR.msgs.push({ who: 'me', t, at: Date.now() }); paintChat();\n    const r = await reply(c, CUR); CUR.msgs.push({ who: 'ta', t: X.plain(r), at: Date.now() }); await S.set('d', D); paintChat();\n};\nwindow.gyxTimeResume = id => { CUR = D.ses.find(x => x.id === id) || null; if (CUR) window.gyxTimeOpen(CUR.cid); };\nwindow.gyxTimeDel = async id => { D.ses = D.ses.filter(x => x.id !== id); if (CUR && CUR.id === id) CUR = null; await S.set('d', D); window.gyxTimeOpen(); };\nwindow.gyxTimeBack = () => { CUR = null; window.gyxTimeOpen(); };\nfunction paintChat() { const b = document.getElementById('gyxTmChat'); if (!b || !CUR) return; const c = X.char(CUR.cid); b.innerHTML = CUR.msgs.map(m => `<div class=\"tm-m ${m.who}\"><span>${X.esc(m.t)}</span></div>`).join('') || `<div class=\"gyx-tip\" style=\"text-align:center\">${X.v('那时候的 TA 还不知道你会来。', '你从以后来，TA 还什么都不知道。', '说点什么吧，别吓到 TA。')}</div>`; b.scrollTop = 1e9; }\nwindow.gyxTimeOpen = function (who) {\n    const c = X.char(who || (CUR && CUR.cid)) || X.cur(); if (!c) return; const cid = String(c.id);\n    if (CUR && CUR.cid === cid) {\n        X.panel('gyxTmOv', `${CUR.date > Date.now() ? '🔮' : '⏳'} ${fmt(CUR.date)}的 ${X.esc(X.name(c))}`, `<div class=\"gyx-tip\">${ago(CUR.date)}的 TA。这里聊的不会进现在 TA 的记忆。<a style=\"float:right;cursor:pointer\" onclick=\"gyxTimeBack()\">← 换一天</a></div><div id=\"gyxTmChat\" class=\"tm-chat\"></div><div class=\"gyx-row\"><input id=\"gyxTmIn\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"对那时候的 TA 说…\" onkeydown=\"if(event.key==='Enter')gyxTimeSend()\"><button class=\"gyx-btn\" onclick=\"gyxTimeSend()\">发送</button></div>`, CUR.date > Date.now() ? 'tm fu' : 'tm');\n        paintChat(); return;\n    }\n    const all = H(cid), first = all.length ? all[0].timestamp : Date.now(), days = [];\n    [1, 7, 30, 90, 180, 365].forEach(n => { const t = Date.now() - n * 864e5; if (t > first) days.push(t); }); if (all.length) days.push(first + 36e5);\n    X.panel('gyxTmOv', '⏳ 时光机', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxTimeOpen')}</div><div class=\"gyx-tip\">选一天，去见那时候的 TA。TA 只知道那天以前的事。</div>\n        <div class=\"gyx-row\">${days.map(t => `<span class=\"gyx-chip\" onclick=\"gyxTimeGo('${cid}',${t})\">${t === first + 36e5 ? '刚认识那天' : ago(t)}</span>`).join('') || '<span class=\"gyx-tip\">你们还没聊过，没有过去可以去。</span>'}</div>\n        <div class=\"tm-h\">🔮 往前开：去见以后的 TA</div><div class=\"gyx-row\">${[1, 3, 5, 10].map(y => `<span class=\"gyx-chip tm-fu\" onclick=\"gyxTimeGo('${cid}',${Date.now() + y * 365 * 864e5})\">${y} 年后</span>`).join('')}</div>\n        <div class=\"gyx-row\"><input type=\"date\" id=\"gyxTmD\" class=\"gyx-who\" value=\"${X.day(new Date(Math.max(first, Date.now() - 30 * 864e5)))}\"><button class=\"gyx-btn\" onclick=\"gyxTimeGo('${cid}',new Date(document.getElementById('gyxTmD').value+'T23:59').getTime())\">去这天</button></div>\n        <div class=\"tm-h\">去过的</div>${D.ses.filter(x => x.cid === cid).slice(0, 30).map(x => `<div class=\"tm-it\" onclick=\"gyxTimeResume('${x.id}')\"><b>${fmt(x.date)}</b><em>${X.esc((x.msgs.find(m => m.who === 'ta') || {}).t || '还没说话')}</em><i onclick=\"event.stopPropagation();gyxTimeDel('${x.id}')\">删</i></div>`).join('') || '<div class=\"gyx-tip\">还没去过</div>'}`);\n};\nX.action({ key: 'gyx_time', label: '翻到以前自己说过的话，跟她聊聊那时候', hint: '那时候的我们', need: c => H(String(c.id)).filter(m => String(m.sender) === String(c.id) && Date.now() - m.timestamp > 20 * 864e5).length > 3,\n    run: async c => { const L = H(String(c.id)).filter(m => String(m.sender) === String(c.id) && Date.now() - m.timestamp > 20 * 864e5); const m = X.pick(L); return (await X.reach(c, `你翻到${ago(m.timestamp)}自己说过的一句话：「${X.plain(m.text).slice(0, 60)}」。跟她聊聊那时候的你们，和现在比有什么不一样`)) ? '翻到了以前的自己' : null; } }, 'gyxTime');\nX.today(() => { const rows = []; X.chars().forEach(c => { const y = H(String(c.id)).filter(m => { const d = new Date(m.timestamp), n = new Date(); return d.getMonth() === n.getMonth() && d.getDate() === n.getDate() && d.getFullYear() < n.getFullYear(); }); if (y.length) rows.push({ t: '往年今天', x: `${X.esc(X.name(c))}：${X.esc(X.plain(y[0].text).slice(0, 24))}`, go: `gyxTimeGo('${c.id}',${y[y.length - 1].timestamp})` }); }); return { title: '⏳ 时光机', rows }; }, 'gyxTime');\nX.widget('gyxTimeW', { n: '时光机', sizes: ['s', 'm'], tap: () => window.gyxTimeOpen(), r: w => { const c = X.cur(); const L = c ? H(String(c.id)).filter(m => String(m.sender) === String(c.id) && Date.now() - m.timestamp > 7 * 864e5) : []; const m = L.length ? L[Math.floor(Date.now() / 36e5) % L.length] : null; return X.gw(w, '⏳', '时光机', m ? [ago(m.timestamp), X.esc(X.plain